def cli(tool):
    args = sys.argv[1:]
    as_json = False
    if "--json" in args:
        as_json = True
        args = [a for a in args if a != "--json"]
    r = call(tool, *args)
    if as_json:
        print(json.dumps({"ok": r.ok, "text": r.text, "data": r.data}))
    elif r.text:
        print(r.text)
    sys.exit(r.code)
